<?php
declare(strict_types=1);require __DIR__.'/app/request-distribution.php';$user=require_verified();$id=marketplace_text($_GET,'id',36,true);$request=request_owned($user,$id);$links=rows('SELECT sl.*,c.channel campaign_channel FROM request_share_links sl LEFT JOIN distribution_campaigns c ON c.id=sl.campaign_id WHERE sl.request_id=? AND sl.revoked_at IS NULL ORDER BY sl.created_at DESC',[$id]);$campaigns=rows('SELECT * FROM distribution_campaigns WHERE request_id=? ORDER BY created_at DESC',[$id]);$invitations=rows('SELECT i.*,sl.token FROM supplier_invitations i JOIN request_share_links sl ON sl.id=i.share_link_id WHERE i.request_id=? ORDER BY i.sent_at DESC',[$id]);$external=rows('SELECT * FROM external_supplier_responses WHERE request_id=? ORDER BY submitted_at DESC',[$id]);$events=rows('SELECT event_type,occurred_at FROM campaign_events WHERE request_id=? ORDER BY occurred_at DESC LIMIT 50',[$id]);$selectedToken=(string)($_GET['share']??($links[0]['token']??''));$active='marketplace';$pageTitle='Share & distribute request';require __DIR__.'/includes/operations-header.php';?>
<section class="page-heading"><div><p class="eyebrow">PROCUREMENT · DISTRIBUTION</p><h1>Share & distribute request</h1><p><?= e($request['title']) ?></p></div><div class="page-actions"><a class="secondary" href="requests?view=detail&id=<?= e($id) ?>">Back to request</a></div></section>
<section class="distribution-grid"><article class="panel"><h2>Request Card & link</h2><p>Create a portable card with a secure link and QR placeholder.</p><form action="request-distribution-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="share.create"><input type="hidden" name="request_id" value="<?= e($id) ?>"><button class="primary">Generate share card</button></form><?php if($selectedToken):?><div class="share-link-row"><input readonly value="request-share?t=<?= e($selectedToken) ?>"><button type="button" data-copy-request-link>Copy link</button><button type="button" data-open-request-card>Open card</button></div><?php endif;?></article>
<article class="panel"><h2>Start distribution campaign</h2><form action="request-distribution-action" method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="campaign.create"><input type="hidden" name="request_id" value="<?= e($id) ?>"><label>Channel<select name="channel"><option>SUPPLIER_NETWORK</option><option>EMAIL</option><option>WHATSAPP</option><option>DIRECT_LINK</option><option>SOCIAL</option><option>SELECTED_SUPPLIERS</option></select></label><label>Audience<input name="audience" placeholder="Relevant equipment owners"></label><label class="full">Approved message<textarea name="approved_content">Equipment required: <?= e($request['title']) ?></textarea></label><div class="full"><button class="primary">Start campaign</button></div></form></article>
<article class="panel"><h2>Invite supplier privately</h2><form action="request-distribution-action" method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="invitation.create"><input type="hidden" name="request_id" value="<?= e($id) ?>"><label>Name<input name="contact_name"></label><label>Email<input type="email" name="contact_email"></label><label>Phone<input name="contact_phone"></label><label>Channel<select name="channel"><option>EMAIL</option><option>WHATSAPP</option><option>DIRECT_LINK</option><option>SUPPLIER_NETWORK</option></select></label><div class="full"><button class="primary">Create invitation</button></div></form></article></section>
<section class="manage-table"><header><h2>External responses</h2></header><?php if(!$external):?><p>No external supplier responses yet.</p><?php else:?><div class="market-table-wrap"><table><thead><tr><th>Supplier</th><th>Equipment</th><th>Commercial</th><th>Status</th><th>Submitted</th></tr></thead><tbody><?php foreach($external as $response):?><tr><td><strong><?= e($response['company_name']) ?></strong><small><?= e($response['contact_name'].' · '.$response['contact_email']) ?></small></td><td><?= e($response['equipment_description']) ?></td><td><?= e($response['currency'].' '.number_format((float)$response['amount'],2).' · '.$response['pricing_basis']) ?></td><td><span class="request-badge"><?= e($response['status']) ?> · UNVERIFIED</span></td><td><?= e($response['submitted_at']) ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="manage-table"><header><h2>Distribution activity</h2></header><div class="transaction-activity"><?php foreach($events as $event):?><article><span><?= e($event['occurred_at']) ?></span><strong><?= e(str_replace('_',' ',$event['event_type'])) ?></strong></article><?php endforeach;?></div></section>
<?php if($selectedToken):?><dialog class="request-share-card-modal" data-request-card-modal><div class="share-card-modal-head"><div><p>SHARE REQUEST</p><h2>Equipment required</h2></div><button type="button" data-close-request-card>×</button></div><canvas width="620" height="1050" data-request-card-canvas></canvas><div class="share-card-actions"><button type="button" data-request-card-download>Download JPEG</button><button type="button" data-copy-request-link>Copy link</button></div></dialog><script type="application/json" data-request-card-data><?= json_encode(['title'=>$request['title'],'quantity'=>$request['quantity_required'],'equipment'=>$request['equipment_type'],'intent'=>$request['intent'],'location'=>$request['location_name'],'required_from'=>$request['required_from'],'required_until'=>$request['required_until'],'deadline'=>$request['response_deadline'],'request_id'=>$request['id'],'path'=>'request-share?t='.$selectedToken],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?></script><script src="assets/js/request-share-card.js" defer></script><?php endif;?>
